#!/usr/bin/env python3
"""
Read an allocation CSV (from predict_next.py or walkforward_sim) and place orders on Robinhood.

Safety
- Defaults to --dry_run so no orders are sent.
- Requires robin_stocks (pip install robin_stocks) and Robinhood credentials.
- Use environment variables for credentials and 2FA: RH_USERNAME, RH_PASSWORD, RH_MFA (optional).

CSV expectations
- Columns: ticker, weight, dollars, (optional) shares
- If shares missing, will compute shares = floor(dollars / last_price).
"""

import argparse
import datetime
import math
import os
import time
from typing import List

import pandas as pd

# Approximate ET using UTC-4 (EDT offset; close enough for scheduling purposes)
MARKET_OPEN_ET = datetime.time(9, 30)


def rh_login():
    try:
        import robin_stocks.robinhood as r
    except Exception as e:
        raise SystemExit("Please pip install robin_stocks to use this script") from e

    user = os.getenv("RH_USERNAME")
    pwd = os.getenv("RH_PASSWORD")
    mfa = os.getenv("RH_MFA")
    if not user or not pwd:
        raise SystemExit("Set RH_USERNAME and RH_PASSWORD in your environment")
    r.login(username=user, password=pwd, mfa_code=mfa)
    return r


def fetch_last_price(r, symbol: str) -> float:
    try:
        q = r.get_latest_price(symbol, includeExtendedHours=False)
        if q and q[0]:
            return float(q[0])
    except Exception:
        pass
    return float("nan")


def execute_orders(args) -> None:
    """Read the allocation CSV and place (or print) orders."""
    df = pd.read_csv(args.alloc_csv)
    if "ticker" not in df.columns or "dollars" not in df.columns:
        raise SystemExit("alloc_csv must include 'ticker' and 'dollars' columns")

    orders = []
    r = None if args.dry_run else rh_login()

    for _, row in df.iterrows():
        sym = str(row["ticker"]).strip().upper()
        dollars = float(row["dollars"]) if not pd.isna(row["dollars"]) else 0.0
        if dollars < args.min_dollars:
            continue
        shares = None
        if "shares" in df.columns and not pd.isna(row["shares"]):
            shares = float(row["shares"])
        else:
            px = fetch_last_price(r, sym) if r else float("nan")
            if not (px and math.isfinite(px) and px > 0):
                continue
            shares = math.floor(dollars / px)
        if shares <= 0:
            continue

        orders.append((sym, args.side, shares))

    if not orders:
        print("No eligible orders.")
        return

    if args.dry_run:
        print("DRY RUN — Orders:")
        for sym, side, shares in orders:
            print(f"{side.upper()} {shares} {sym}")
        return

    import robin_stocks.robinhood as rh
    ok, fail = 0, 0
    for sym, side, shares in orders:
        try:
            if side == "buy":
                rh.order_buy_market(sym, shares)
            else:
                rh.order_sell_market(sym, shares)
            ok += 1
        except Exception as e:
            print(f"Failed {side} {sym}: {e}")
            fail += 1
    print(f"Submitted {ok} orders; {fail} failed")


def _seconds_until_market_open() -> float:
    """Return seconds until the next 9:30 AM ET (approximated as UTC-4)."""
    now_et = datetime.datetime.utcnow() + datetime.timedelta(hours=-4)
    target_today = datetime.datetime.combine(now_et.date(), MARKET_OPEN_ET)
    if now_et >= target_today:
        # Already past today's open — aim for tomorrow
        target_today += datetime.timedelta(days=1)
    return (target_today - now_et).total_seconds()


def _wait_for_csv(path: str, timeout_seconds: int = 600, poll_interval: int = 60) -> bool:
    """Poll until the CSV exists or timeout expires. Returns True if found."""
    elapsed = 0
    while elapsed < timeout_seconds:
        if os.path.exists(path):
            return True
        print(f"[loop] Waiting for {path} ... ({elapsed}s elapsed)")
        time.sleep(poll_interval)
        elapsed += poll_interval
    return False


def run_loop(args) -> None:
    """Run the executor once per trading day, waking at 9:30 AM ET."""
    print("[loop] Starting daily loop. Press Ctrl+C to stop.")
    while True:
        secs = _seconds_until_market_open()
        wake_et = datetime.datetime.utcnow() + datetime.timedelta(hours=-4, seconds=secs)
        print(f"[loop] Sleeping {secs:.0f}s until market open (~{wake_et.strftime('%Y-%m-%d %H:%M')} ET)")
        time.sleep(secs)

        print(f"[loop] Market open — waiting for CSV: {args.alloc_csv}")
        found = _wait_for_csv(args.alloc_csv)
        if not found:
            print(f"[loop] WARNING: {args.alloc_csv} not found after 10 minutes. Skipping today's session.")
        else:
            print(f"[loop] CSV found — executing orders.")
            try:
                execute_orders(args)
            except Exception as e:
                print(f"[loop] ERROR during order execution: {e}")

        # Sleep briefly before looping so we don't re-trigger on the same minute
        time.sleep(60)


def main() -> None:
    p = argparse.ArgumentParser(description="Submit Robinhood orders from an allocation CSV")
    p.add_argument("--alloc_csv", required=True, help="CSV with columns: ticker, weight, dollars, shares (optional)")
    p.add_argument("--side", default="buy", choices=["buy", "sell"], help="Order side")
    p.add_argument("--time_in_force", default="gfd", help="Time in force (gfd, gtc, etc.)")
    p.add_argument("--dry_run", action="store_true", help="Print orders instead of submitting")
    p.add_argument("--min_dollars", type=float, default=50.0, help="Skip tiny orders below this size")
    p.add_argument("--loop", action="store_true", help="Run once per trading day at 9:30 AM ET (dry-run by default)")
    args = p.parse_args()

    if args.loop:
        run_loop(args)
    else:
        execute_orders(args)


if __name__ == "__main__":
    main()
